-- +goose Up
-- Phase 3 (3-4): schema auth holds Better Auth's tables (00041, generated by its pinned CLI). The
-- identity service connects as goal_auth, which gets DML on those tables and nothing else; goal_app
-- gets no privilege on the schema at all and reads it only through definer functions (later
-- migrations). goal_owner owns it, like everything else. goal db init creates goal_auth and gives
-- goal_owner CREATE on the database; goald refuses to migrate while goal_auth is missing.
CREATE SCHEMA auth AUTHORIZATION goal_owner;
GRANT USAGE ON SCHEMA auth TO goal_auth;

-- UUIDv7 without PostgreSQL 18's uuidv7(), so the schema runs on older managed versions
-- (architecture "IDs"): the 48-bit Unix time in milliseconds, then version 7 over v4's random
-- bits. The default of Better Auth's id columns; ids Goal generates come from Go.
CREATE FUNCTION goal_uuidv7() RETURNS uuid LANGUAGE sql VOLATILE AS $$
  SELECT encode(set_bit(set_bit(overlay(uuid_send(gen_random_uuid())
    PLACING substring(int8send((extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3)
    FROM 1 FOR 6), 52, 1), 53, 1), 'hex')::uuid
$$;
REVOKE ALL ON FUNCTION goal_uuidv7() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION goal_uuidv7() TO goal_auth, goal_app;
